# -*- coding: utf-8 -*-
"""
列车运行理论能耗仿真模型 (理论机械功版)
同步逻辑：
    1. 加速度：Discrete Derivative + 1阶巴特沃斯滤波 (0.2Hz, Tustin离散化)
    2. 线路阻力：坡道与曲线均采用每节车20切片分布式算法
    3. 启动阻力：严格执行 MATLAB eps 触发逻辑 (49/1000 kN/t)
    4. 理论核心：合力限幅 Saturation(0, inf) 后直接计算机械功，不计效率损失
"""

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import math
import os
import sys
import matplotlib.pyplot as plt
import platform

