# ---------------------------------------------------------
# 1. 离散求导模块 (严格复刻 Simulink 逻辑)
# ---------------------------------------------------------
class SimulinkDiscreteDerivative:
    def __init__(self, Ts=0.05, K=1.0, IC=0.0):
        self.Ts = Ts
        self.K = K
        self.state = IC 

    def update(self, u):
        current_weighted_input = (self.K * u) / self.Ts
        y = current_weighted_input - self.state
        self.state = current_weighted_input
        return y

# ---------------------------------------------------------
# 2. 理论能耗仿真模型类
# ---------------------------------------------------------
class TrainTheoreticalEnergyModel:
    def __init__(self, excel_path):
        print(f"🔄 正在初始化理论能耗模型 (不包含效率损耗)...")
        
        # --- 物理参数 ---
        self.P_a, self.P_b = 1.65, 0.0247   # 中间车 Davis
        self.P_c, self.P_d = 0.78, 0.0028   # 头尾车 Davis
        self.P_e, self.P_f = 0.028, 0.0078  # 气动
        
        self.gain_trailer = 1.05            # 拖车惯性系数
        self.gain_motor = 1.10              # 动车惯性系数
        
        self.num_cars = 6
        self.car_length = 20.0
        self.g = 9.8
        self.dt = 0.05                      
        
        # --- 1阶巴特沃斯 Tustin 离散化系数 (fc=0.2Hz) ---
        wc = 0.2 * 2 * np.pi
        denom = (2.0 / self.dt) + wc
        self.filt_b0 = wc / denom                   
        self.filt_b1 = self.filt_b0                  
        self.filt_a1 = (wc - (2.0 / self.dt)) / denom 
        
        self.eps = sys.float_info.epsilon   

        # --- 状态与数据加载 ---
        self.derivative_module = SimulinkDiscreteDerivative(Ts=self.dt, K=1.0, IC=0.0)
        self.last_v_ms = 0.0
        self.last_raw_acc = 0.0
        self.last_filt_acc = 0.0
        self.current_dist = 0.0
        self.total_theoretical_energy_kwh = 0.0

        self.load_real_gradient_data()
        self.load_real_curve_data()
        self.load_excel_data(excel_path)
        
        self.station_locs = np.array([0, 1428, 3445, 4777, 5604, 7464, 8550, 9534, 11345, 12500, 
                                      13952, 15166, 16123, 17921, 19228, 20208, 21073, 21797, 
                                      23359, 24353, 26230, 27311, 28269, 29102, 32778, 34909, 36502])

